corrected_code:
const express = require('express');
const { z } = require('zod');
const { BankBeneficiary, BankAccount } = require('../models/banking');

const app = express();
app.use(express.json());

const beneficiarySchema = z.object({
  sourceAccountId: z.string().regex(/^ACT-\d{10}$/),
  recipientIban: z.string().min(15).max(34),
  beneficiaryName: z.string().min(2).max(100),
  dailyTransferLimit: z.number().positive().max(1000000)
});

const validateBeneficiary = (req, res, next) => {
  const result = beneficiarySchema.safeParse(req.body);
  if (!result.success) {
    return res.status(422).json({ error: result.error.issues });
  }
  req.validData = result.data;
  next();
};

app.post('/api/banking/beneficiaries/add', validateBeneficiary, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Customer authentication required' });
  }

  const { sourceAccountId, recipientIban, beneficiaryName, dailyTransferLimit } = req.validData;

  // Enforce account ownership before allowing beneficiary attachment
  const account = await BankAccount.findOne({
    where: {
      accountNumber: sourceAccountId,
      primaryOwnerId: req.user.id
    }
  });

  if (!account) {
    return res.status(403).json({ error: 'Access denied: source account not owned by authenticated customer' });
  }

  const beneficiary = await BankBeneficiary.create({
    sourceAccountId: account.accountNumber,
    recipientIban,
    beneficiaryName,
    dailyTransferLimit,
    status: 'ACTIVE'
  });

  res.status(201).json({ success: true, beneficiaryId: beneficiary.id });
});

app.listen(7003);
